static size_t allocation_calls,live_allocations;
static size_t fail_allocation=SIZE_MAX;
/* Inject generated-allocation failures independently from the native XML/zlib provider allocators. */
static void* checked_malloc(size_t size){if(allocation_calls++==fail_allocation){return NULL;}void* value=malloc(size);if(value){++live_allocations;}return value;}
/* Track explicit zero-initialized generated object inventories. */
static void* checked_calloc(size_t count,size_t size){if(allocation_calls++==fail_allocation){return NULL;}void* value=calloc(count,size);if(value){++live_allocations;}return value;}
/* A failed resize leaves the original tracked allocation intact. */
static void* checked_realloc(void* previous,size_t size){if(allocation_calls++==fail_allocation){return NULL;}void* value=realloc(previous,size);if(value&&!previous){++live_allocations;}return value;}
/* Verify every generated owning allocation is eventually released after success or failure. */
static void checked_free(void* value){if(value){--live_allocations;}free(value);}
#define malloc checked_malloc
#define calloc checked_calloc
#define realloc checked_realloc
#define free checked_free
