/* Resolve only test-owned relative paths beneath the explicitly supplied fixture directory. */
static void path(char* result,size_t capacity,const char* name){const int size=snprintf(result,capacity,"%s/%s",directory,name);require(size>=0&&(size_t)size<capacity,"fixture path bounds");}
/* Read small independently produced fixture bytes with an extra private NUL sentinel. */
static srl_buffer load(const char* name){char filename[4097];path(filename,sizeof(filename),name);FILE* file=fopen(filename,"rb");require(file!=NULL,"open fixture");require(!fseek(file,0,SEEK_END),"seek fixture");const long size=ftell(file);require(size>=0&&!fseek(file,0,SEEK_SET),"measure fixture");srl_buffer value={0};require(srl_reserve(&value,(size_t)size+1),"fixture allocation");value.size=(size_t)size;require(fread(value.data,1,value.size,file)==value.size,"read fixture");require(!fclose(file),"close fixture");value.data[value.size]=0;return value;}
/* Retain actual native producer bytes for the independent Python ZIP/XML consumer. */
static void save(const char* name,const srl_buffer* bytes){char filename[4097];path(filename,sizeof(filename),name);FILE* file=fopen(filename,"wb");require(file!=NULL,"open output");require(fwrite(bytes->data,1,bytes->size,file)==bytes->size,"write output");require(!fclose(file),"close output");}
/* Compare exact complete-message byte extents. */
static bool equal(const srl_buffer* left,const srl_buffer* right){return left->size==right->size&&(!left->size||!memcmp(left->data,right->data,left->size));}
/* Inject a caller-owned full-Save failure at one precise publication stage. */
static int fault(void* context,const char* stage){return !strcmp((const char*)context,stage)?701:0;}
typedef struct transport {const uint8_t* bytes;size_t size,position,calls;srl_buffer output;int failure;} transport;
/* Return legal short reads without seeking, closing, or retaining the caller's transport. */
static int source(void* context,uint8_t* bytes,size_t capacity,size_t* count){transport* value=(transport*)context;++value->calls;if(value->failure){return value->failure;}*count=value->size-value->position;if(*count>capacity){*count=capacity;}if(*count>3){*count=3;}if(*count){memcpy(bytes,value->bytes+value->position,*count);}value->position+=*count;return 0;}
/* Accept legal short writes and preserve arbitrary original transport status codes. */
static int sink(void* context,const uint8_t* bytes,size_t size,size_t* written){transport* value=(transport*)context;++value->calls;if(value->failure){return value->failure;}*written=size>5?5:size;require(srl_reserve(&value->output,*written),"short sink allocation");memcpy(value->output.data+value->output.size,bytes,*written);value->output.size+=*written;return 0;}
/* Observe cancellation through the borrowed operation context. */
static bool cancelled(void* context){size_t* polls=(size_t*)context;return ++*polls>=3;}
/* Return the cancellation state requested by the final pre-publication callback. */
static bool publication_cancelled(void* context){return *(bool*)context;}
/* Request cancellation at the publication boundary while returning ordinary callback success. */
static int cancel_publication(void* context,const char* stage){if(!strcmp(stage,"before_replace")){*(bool*)context=true;}return 0;}
/* Verify that successful, bounded and canceled memory spools leave their private temp directory empty. */
static bool spool_clean(void){char filename[4097];
#if defined(_WIN32)
  path(filename,sizeof(filename),"spool-temp/*");WIN32_FIND_DATAA data;HANDLE handle=FindFirstFileA(filename,&data);if(handle==INVALID_HANDLE_VALUE){return GetLastError()==ERROR_FILE_NOT_FOUND;}bool clean=true;do{if(strcmp(data.cFileName,".")&&strcmp(data.cFileName,"..")){clean=false;break;}}while(FindNextFileA(handle,&data));FindClose(handle);return clean;
#else
  path(filename,sizeof(filename),"spool-temp");DIR* handle=opendir(filename);if(!handle){return false;}bool clean=true;struct dirent* entry;while((entry=readdir(handle))!=NULL){if(strcmp(entry->d_name,".")&&strcmp(entry->d_name,"..")){clean=false;break;}}closedir(handle);return clean;
#endif
}
